//! Compact static string tables (prompt 020 §3.9, ADR-0026 size plan): one blob plus `u16`
//! offsets instead of a `[(&str, &str); N]` array, which costs 32 bytes and four relocations
//! per entry. Keys are sorted by bytes and unique, so lookups binary-search in place (F-39).
//! Generated by `tools/pack_table.py`.

/// A sorted (key, value) table packed into one string.
pub struct Packed {
    /// All keys and values back to back.
    pub blob: &'static str,
    /// `2 * len + 1` ascending offsets: key `i` is `off[2i]..off[2i+1]`, its value
    /// `off[2i+1]..off[2i+2]`.
    pub off: &'static [u16],
}

impl Packed {
    /// Number of entries.
    pub fn len(&self) -> usize {
        self.off.len().saturating_sub(1) / 2
    }

    /// `true` when the table has no entries.
    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }

    fn part(&self, j: usize) -> &'static str {
        let (Some(&a), Some(&b)) = (self.off.get(j), self.off.get(j + 1)) else {
            return "";
        };
        self.blob.get(usize::from(a)..usize::from(b)).unwrap_or("")
    }

    /// Entry `i` as (key, value).
    pub fn get(&self, i: usize) -> Option<(&'static str, &'static str)> {
        (i < self.len()).then(|| (self.part(2 * i), self.part(2 * i + 1)))
    }

    /// All entries in key order.
    pub fn iter(&self) -> impl Iterator<Item = (&'static str, &'static str)> + '_ {
        (0..self.len()).filter_map(|i| self.get(i))
    }

    /// The value for `key` (binary search).
    pub fn find(&self, key: &str) -> Option<&'static str> {
        let (mut lo, mut hi) = (0, self.len());
        while lo < hi {
            let mid = lo + (hi - lo) / 2;
            match self.part(2 * mid).as_bytes().cmp(key.as_bytes()) {
                std::cmp::Ordering::Less => lo = mid + 1,
                std::cmp::Ordering::Greater => hi = mid,
                std::cmp::Ordering::Equal => return Some(self.part(2 * mid + 1)),
            }
        }
        None
    }
}

#[cfg(test)]
mod tests {
    use super::Packed;

    static T: Packed = Packed {
        blob: "aXbbYc",
        off: &[0, 1, 2, 4, 5, 6, 6],
    };

    #[test]
    fn packed_table_reads_and_searches() {
        assert_eq!(T.len(), 3);
        assert_eq!(T.get(0), Some(("a", "X")));
        assert_eq!(T.get(1), Some(("bb", "Y")));
        assert_eq!(T.get(2), Some(("c", "")));
        assert_eq!(T.get(3), None);
        assert_eq!(T.find("bb"), Some("Y"));
        assert_eq!(T.find("c"), Some(""));
        assert_eq!(T.find("b"), None);
        assert_eq!(T.find("zz"), None);
        assert_eq!(T.iter().count(), 3);
    }

    #[test]
    fn generated_tables_are_whole_sorted_and_on_char_boundaries() {
        for (t, n) in [
            (&crate::html_entities::ENTITIES, 2231),
            (&crate::emoji_table::EMOJI, 1913),
        ] {
            assert_eq!(t.len(), n);
            assert_eq!(usize::from(*t.off.last().unwrap_or(&0)), t.blob.len());
            assert!(t.off.windows(2).all(|w| w[0] <= w[1]));
            assert!(
                t.off
                    .iter()
                    .all(|&o| t.blob.is_char_boundary(usize::from(o)))
            );
            let keys: Vec<&str> = t.iter().map(|(k, _)| k).collect();
            assert!(keys.windows(2).all(|w| w[0].as_bytes() < w[1].as_bytes()));
            assert!(t.iter().all(|(k, v)| !k.is_empty() && !v.is_empty()));
            for (k, v) in t.iter() {
                assert_eq!(t.find(k), Some(v), "{k}");
            }
        }
        let e = &crate::html_entities::ENTITIES;
        assert_eq!(e.find("amp;"), Some("&"));
        assert_eq!(e.find("nbsp"), Some("\u{a0}"));
        assert_eq!(e.find("NewLine;"), Some("\n"));
        assert_eq!(e.find("Tab;"), Some("\t"));
        assert_eq!(e.find("ThinSpace;"), Some("\u{2009}"));
        assert_eq!(e.find("Afr;"), Some("\u{1d504}"));
        assert_eq!(crate::emoji_table::EMOJI.find("+1"), Some("\u{1f44d}"));
        assert_eq!(
            crate::emoji_table::EMOJI.find("afghanistan"),
            Some("\u{1f1e6}\u{1f1eb}")
        );
    }
}
